package forge

import "gno.land/p/nt/avl/v0"

// Issue is a discussion thread bound to a repo. Anyone with an address may open
// one: the spam gate is not a moderator, it is that the author pays gas and
// locks the storage deposit for every byte they write.
type Issue struct {
	ID        int64
	Title     string
	Body      string
	Author    address
	Open      bool
	Labels    []string
	CreatedAt int64
	UpdatedAt int64

	comments    *avl.Tree // padded id -> *Comment
	nextComment int64
}

// Comment is one reply, on an issue or on a change request.
type Comment struct {
	ID        int64
	Author    address
	Body      string
	CreatedAt int64
}

// OpenIssue files an issue. Permissionless by design.
func (r *Repo) OpenIssue(actor address, height int64, title, body string, labels []string) (*Issue, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if title == "" || !ValidLine(title, MaxTitleLen) {
		return nil, ErrInvalidText
	}
	if !ValidText(body, MaxBodyLen) {
		return nil, ErrInvalidText
	}
	if err := checkLabels(labels); err != nil {
		return nil, err
	}
	i := &Issue{
		ID:        r.nextIssue,
		Title:     title,
		Body:      body,
		Author:    actor,
		Open:      true,
		Labels:    append([]string{}, labels...),
		CreatedAt: height,
		UpdatedAt: height,
		comments:  avl.NewTree(),
	}
	r.issues.Set(seqKey(i.ID), i)
	r.nextIssue++
	return i, nil
}

// CommentIssue appends a reply. Closed issues still take comments (closing is a
// triage state, not a gag); an archived repo takes none.
func (r *Repo) CommentIssue(actor address, height, id int64, body string) (*Comment, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return nil, ErrIssueNotFound
	}
	if body == "" || !ValidText(body, MaxCommentLen) {
		return nil, ErrInvalidText
	}
	c := &Comment{ID: i.nextComment, Author: actor, Body: body, CreatedAt: height}
	i.comments.Set(seqKey(c.ID), c)
	i.nextComment++
	i.UpdatedAt = height
	return c, nil
}

// SetIssueOpen closes or reopens an issue. The author can always close their
// own; maintainers can close anyone's.
func (r *Repo) SetIssueOpen(actor address, height, id int64, open bool) error {
	if r.Archived {
		return ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return ErrIssueNotFound
	}
	if i.Author != actor && !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	i.Open = open
	i.UpdatedAt = height
	return nil
}

// SetIssueLabels replaces an issue's labels. Triage is a maintainer action.
func (r *Repo) SetIssueLabels(actor address, height, id int64, labels []string) error {
	if r.Archived {
		return ErrRepoArchived
	}
	i := r.Issue(id)
	if i == nil {
		return ErrIssueNotFound
	}
	if !r.Can(actor, RoleMaintainer) {
		return ErrUnauthorized
	}
	if err := checkLabels(labels); err != nil {
		return err
	}
	i.Labels = append([]string{}, labels...)
	i.UpdatedAt = height
	return nil
}

// Issue returns an issue by id, or nil.
func (r *Repo) Issue(id int64) *Issue {
	v := r.issues.Get(seqKey(id))
	if v == nil {
		return nil
	}
	return v.(*Issue)
}

// IterateIssues walks issues newest-first.
func (r *Repo) IterateIssues(offset, count int, cb func(*Issue) bool) {
	if count <= 0 {
		count = r.issues.Size()
	}
	r.issues.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Issue))
	})
}

// OpenIssueCount counts issues still open.
func (r *Repo) OpenIssueCount() int {
	n := 0
	r.issues.Iterate("", "", func(_ string, value any) bool {
		if value.(*Issue).Open {
			n++
		}
		return false
	})
	return n
}

// CommentCount is the number of replies on the issue.
func (i *Issue) CommentCount() int { return i.comments.Size() }

// IterateComments walks replies oldest-first.
func (i *Issue) IterateComments(offset, count int, cb func(*Comment) bool) {
	if count <= 0 {
		count = i.comments.Size()
	}
	i.comments.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*Comment))
	})
}

func checkLabels(labels []string) error {
	if len(labels) > MaxLabels {
		return ErrTooMany
	}
	for _, l := range labels {
		if !ValidLabel(l) {
			return ErrInvalidText
		}
	}
	return nil
}

package forge

import "strings"

// MaxPkgPathLen bounds a published package path. gno.land's own paths are far
// shorter; the cap exists because every stored byte is a storage deposit
// somebody pays.
const MaxPkgPathLen = 256

// Package is the claim that a repo publishes a deployed package path.
//
// This is the join nothing else in the forge could express. A repo id is
// "<namespace>/<name>", exactly two parts, so `r/moul/home` can never be one:
// there was no way to ask "which repo publishes this package path", which is
// the first question a reader arriving from an explorer has.
//
// The claim is deliberately one-directional and unverified. A realm cannot ask
// the chain who deployed a path, so the forge cannot check that the repo really
// is the source of the package. What it can guarantee is that only someone with
// write access to the repo said so, and that the namespace of the repo is
// governed by r/sys/users. A reader weighs the claim the way they weigh a
// go.mod: it says where the author says the source lives.
type Package struct {
	Path        string // "gno.land/r/moul/home", the deployed package path
	RepoID      string
	Ref         string // the ref this was published from, "" if unstated
	OID         string // the object id, "" if unstated
	Tag         string // the release tag, "" if not published as part of one
	PublishedAt int64  // block height
	PublishedBy address
}

// ValidPkgPath reports whether s is a plausible gno package path.
//
// Deliberately shallow: it checks shape, not existence, because a realm cannot
// ask the chain whether a path is deployed and a check that only sometimes
// works is worse than one that never claims to.
func ValidPkgPath(s string) bool {
	if s == "" || len(s) > MaxPkgPathLen {
		return false
	}
	if strings.Contains(s, "..") || strings.HasSuffix(s, "/") {
		return false
	}
	parts := strings.Split(s, "/")
	if len(parts) < 3 {
		return false
	}
	for _, p := range parts {
		if p == "" {
			return false
		}
		for i := 0; i < len(p); i++ {
			c := p[i]
			ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
				(c >= '0' && c <= '9') || c == '.' || c == '-' || c == '_'
			if !ok {
				return false
			}
		}
	}
	return true
}

// PublishPackage records that this repo publishes path, and indexes it
// forge-wide so PackageRepo can answer without scanning every repo.
//
// Re-publishing the same path from the same repo overwrites the entry, which is
// what a redeploy is. Publishing a path another repo already claims is refused:
// silently moving it would let any repo owner capture another project's
// package path in an explorer.
func (f *Forge) PublishPackage(actor address, height int64, repoID, path, ref, oid, tag string) (*Package, error) {
	r := f.Repo(repoID)
	if r == nil {
		return nil, ErrRepoNotFound
	}
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleWriter) {
		return nil, ErrUnauthorized
	}
	if !ValidPkgPath(path) {
		return nil, ErrInvalidPkgPath
	}
	if ref != "" && !ValidRefName(ref) {
		return nil, ErrInvalidRefName
	}
	if oid != "" && !ValidOID(oid) {
		return nil, ErrInvalidOID
	}
	if tag != "" && !ValidText(tag, MaxTagLen) {
		return nil, ErrInvalidText
	}
	if owner := f.packages.Get(path); owner != nil {
		if existing := owner.(*Package); existing.RepoID != repoID {
			return nil, ErrPackageClaimed
		}
	}

	p := &Package{
		Path:        path,
		RepoID:      repoID,
		Ref:         ref,
		OID:         oid,
		Tag:         tag,
		PublishedAt: height,
		PublishedBy: actor,
	}
	f.packages.Set(path, p)
	r.packages.Set(path, p)
	return p, nil
}

// UnpublishPackage withdraws the claim. The package stays on chain; only the
// repo's assertion about it goes away.
func (f *Forge) UnpublishPackage(actor address, repoID, path string) error {
	r := f.Repo(repoID)
	if r == nil {
		return ErrRepoNotFound
	}
	if !r.Can(actor, RoleWriter) {
		return ErrUnauthorized
	}
	if _, removed := r.packages.Remove(path); !removed {
		return ErrPackageNotFound
	}
	f.packages.Remove(path)
	return nil
}

// PackageRepo is the lookup an explorer makes: given a deployed path, which
// repo claims to publish it. Returns "" when nobody does.
func (f *Forge) PackageRepo(path string) string {
	v := f.packages.Get(path)
	if v == nil {
		return ""
	}
	return v.(*Package).RepoID
}

// PackageAt returns the full claim for a path, or nil.
func (f *Forge) PackageAt(path string) *Package {
	v := f.packages.Get(path)
	if v == nil {
		return nil
	}
	return v.(*Package)
}

// PackageCount is how many paths the whole forge claims.
func (f *Forge) PackageCount() int { return f.packages.Size() }

// IteratePackages walks every claimed path in the forge, in path order.
func (f *Forge) IteratePackages(offset, count int, cb func(*Package) bool) {
	if count <= 0 {
		count = f.packages.Size()
	}
	f.packages.IterateByOffset(offset, count, func(_ string, v any) bool {
		return cb(v.(*Package))
	})
}

// PackageCount is how many paths this repo claims.
func (r *Repo) PackageCount() int { return r.packages.Size() }

// IteratePackages walks the paths this repo claims, in path order.
func (r *Repo) IteratePackages(offset, count int, cb func(*Package) bool) {
	if count <= 0 {
		count = r.packages.Size()
	}
	r.packages.IterateByOffset(offset, count, func(_ string, v any) bool {
		return cb(v.(*Package))
	})
}

package forge

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

func TestValidPkgPath(t *testing.T) {
	cases := []struct {
		name string
		path string
		want bool
	}{
		{"a realm", "gno.land/r/moul/home", true},
		{"a pure package", "gno.land/p/moul/forge/v1", true},
		{"deep", "gno.land/r/moul/x/daily/asciiart/v0", true},
		{"an address namespace", "gno.land/r/g1abc/thing", true},
		{"underscores and dashes", "gno.land/r/ns/a-b_c", true},
		// Shape only. A realm cannot ask the chain whether a path is deployed,
		// so anything stricter would be a check that only sometimes works.
		{"not deployed but well formed", "gno.land/r/nobody/nothing", true},
		{"empty", "", false},
		{"two parts", "gno.land/r", false},
		{"a traversal", "gno.land/r/../etc", false},
		{"trailing slash", "gno.land/r/moul/home/", false},
		{"an empty element", "gno.land//r/moul", false},
		{"a space", "gno.land/r/moul/my home", false},
		{"a colon", "gno.land/r/moul/home:tab", false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			uassert.Equal(t, tc.want, ValidPkgPath(tc.path))
		})
	}
}

func TestPublishPackageIndexesForgeWide(t *testing.T) {
	f, r := newRepo(t)

	p, err := f.PublishPackage(carol, 200, r.ID, "gno.land/r/moul/home", "refs/heads/main", oid("a"), "")
	urequire.NoError(t, err)
	uassert.Equal(t, "gno.land/r/moul/home", p.Path)
	uassert.Equal(t, r.ID, p.RepoID)
	uassert.Equal(t, int64(200), p.PublishedAt)

	// The lookup an explorer makes: it starts from the path and does not know
	// the repo yet, which is the whole reason the index is forge-wide.
	uassert.Equal(t, r.ID, f.PackageRepo("gno.land/r/moul/home"))
	uassert.Equal(t, "", f.PackageRepo("gno.land/r/someone/else"))
	uassert.Equal(t, 1, f.PackageCount())
	uassert.Equal(t, 1, r.PackageCount())
}

// One repo publishes many paths: gno-contracts publishes 193.
func TestPublishManyPackages(t *testing.T) {
	f, r := newRepo(t)

	paths := []string{
		"gno.land/r/moul/home",
		"gno.land/p/moul/forge/v1",
		"gno.land/r/moul/blog",
	}
	for _, path := range paths {
		_, err := f.PublishPackage(alice, 200, r.ID, path, "", "", "")
		urequire.NoError(t, err)
	}
	uassert.Equal(t, 3, r.PackageCount())

	var seen []string
	r.IteratePackages(0, 0, func(p *Package) bool {
		seen = append(seen, p.Path)
		return false
	})
	// Path order, which is what the tree gives and what a file list wants.
	urequire.Equal(t, 3, len(seen))
	uassert.Equal(t, "gno.land/p/moul/forge/v1", seen[0])
	uassert.Equal(t, "gno.land/r/moul/blog", seen[1])
	uassert.Equal(t, "gno.land/r/moul/home", seen[2])
}

// Re-publishing the same path from the same repo is a redeploy, and overwrites.
func TestRepublishOverwrites(t *testing.T) {
	f, r := newRepo(t)

	_, err := f.PublishPackage(alice, 200, r.ID, "gno.land/r/moul/home", "", oid("a"), "v1.0.0")
	urequire.NoError(t, err)
	_, err = f.PublishPackage(alice, 300, r.ID, "gno.land/r/moul/home", "", oid("b"), "v1.1.0")
	urequire.NoError(t, err)

	uassert.Equal(t, 1, f.PackageCount())
	got := f.PackageAt("gno.land/r/moul/home")
	urequire.True(t, got != nil)
	uassert.Equal(t, oid("b"), got.OID)
	uassert.Equal(t, "v1.1.0", got.Tag)
	uassert.Equal(t, int64(300), got.PublishedAt)
}

// Silently moving a claimed path would let any repo owner capture another
// project's package in every explorer that reads this index.
func TestPublishRefusesAnotherReposPath(t *testing.T) {
	f, r := newRepo(t)
	_, err := f.PublishPackage(alice, 200, r.ID, "gno.land/r/moul/home", "", "", "")
	urequire.NoError(t, err)

	other, err := f.CreateRepo(eve, 210, "eve/squat", "", "")
	urequire.NoError(t, err)

	_, err = f.PublishPackage(eve, 220, other.ID, "gno.land/r/moul/home", "", "", "")
	uassert.ErrorIs(t, err, ErrPackageClaimed)
	uassert.Equal(t, r.ID, f.PackageRepo("gno.land/r/moul/home"))
}

func TestPublishAuthorityAndValidation(t *testing.T) {
	f, r := newRepo(t)

	// dave is a reader, eve is nothing: neither may publish.
	_, err := f.PublishPackage(dave, 200, r.ID, "gno.land/r/moul/home", "", "", "")
	uassert.ErrorIs(t, err, ErrUnauthorized)
	_, err = f.PublishPackage(eve, 200, r.ID, "gno.land/r/moul/home", "", "", "")
	uassert.ErrorIs(t, err, ErrUnauthorized)

	_, err = f.PublishPackage(alice, 200, "nobody/nothing", "gno.land/r/x/y", "", "", "")
	uassert.ErrorIs(t, err, ErrRepoNotFound)

	_, err = f.PublishPackage(alice, 200, r.ID, "not a path", "", "", "")
	uassert.ErrorIs(t, err, ErrInvalidPkgPath)

	_, err = f.PublishPackage(alice, 200, r.ID, "gno.land/r/moul/home", "main", "", "")
	uassert.ErrorIs(t, err, ErrInvalidRefName)

	_, err = f.PublishPackage(alice, 200, r.ID, "gno.land/r/moul/home", "", "nothex", "")
	uassert.ErrorIs(t, err, ErrInvalidOID)

	urequire.NoError(t, r.SetArchived(alice, true))
	_, err = f.PublishPackage(alice, 200, r.ID, "gno.land/r/moul/home", "", "", "")
	uassert.ErrorIs(t, err, ErrRepoArchived)
}

func TestUnpublishClearsBothHalvesOfTheIndex(t *testing.T) {
	f, r := newRepo(t)
	_, err := f.PublishPackage(alice, 200, r.ID, "gno.land/r/moul/home", "", "", "")
	urequire.NoError(t, err)

	uassert.ErrorIs(t, f.UnpublishPackage(dave, r.ID, "gno.land/r/moul/home"), ErrUnauthorized)
	uassert.ErrorIs(t, f.UnpublishPackage(alice, r.ID, "gno.land/r/nothing"), ErrPackageNotFound)

	urequire.NoError(t, f.UnpublishPackage(alice, r.ID, "gno.land/r/moul/home"))
	uassert.Equal(t, 0, f.PackageCount())
	uassert.Equal(t, 0, r.PackageCount())
	uassert.Equal(t, "", f.PackageRepo("gno.land/r/moul/home"))
}

// A fork is not a publisher of its parent's paths.
func TestForkInheritsNoPackages(t *testing.T) {
	f, r := newRepo(t)
	_, err := f.PublishPackage(alice, 200, r.ID, "gno.land/r/moul/home", "", "", "")
	urequire.NoError(t, err)

	child, err := f.Fork(eve, 210, r.ID, "eve/forge")
	urequire.NoError(t, err)
	uassert.Equal(t, 0, child.PackageCount())
	uassert.Equal(t, r.ID, f.PackageRepo("gno.land/r/moul/home"))
}

package forge

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"
)

// Log entry kinds.
const (
	KindCreate = "create" // a ref that did not exist now points somewhere
	KindUpdate = "update" // compare-and-swap succeeded
	KindForce  = "force"  // the tip was replaced without a matching expectation
	KindDelete = "delete" // the ref is gone (the log is not)
	KindMerge  = "merge"  // an update performed by merging a change request
)

// Ref is the current state of one reference. The history of how it got here is
// in the repo log, which nothing can rewrite.
type Ref struct {
	Name      string
	OID       string
	UpdatedAt int64
	UpdatedBy address
}

// LogEntry is one link of the repo's reference log. The log is append-only and
// hash-chained: Digest commits to every earlier entry, so publishing a single
// digest (in a release note, a package manifest, a tweet) pins the entire
// history of every ref up to that point.
type LogEntry struct {
	Seq      int64
	Ref      string
	OldOID   string // "" when the ref did not exist
	NewOID   string // "" on delete
	Actor    address
	Height   int64
	Kind     string
	ChangeID int64 // the merged change, 0 otherwise
	Note     string
	Digest   string // hex sha256 over the previous digest and this entry
}

// EntryDigest computes the chain digest of e given the previous entry's digest.
// It is exported so an off-chain verifier can recompute the chain byte for byte
// from the values it read back; the field order below is the wire format and
// must not change within a version.
func EntryDigest(prev string, e *LogEntry) string {
	fields := []string{
		prev,
		strconv.FormatInt(e.Seq, 10),
		e.Ref,
		e.OldOID,
		e.NewOID,
		e.Actor.String(),
		strconv.FormatInt(e.Height, 10),
		e.Kind,
		strconv.FormatInt(e.ChangeID, 10),
		e.Note,
	}
	sum := sha256.Sum256([]byte(strings.Join(fields, "\n")))
	return hex.EncodeToString(sum[:])
}

// appendLog writes one entry and advances the chain head. Callers have already
// authorized and validated; this never fails.
func (r *Repo) appendLog(actor address, height int64, ref, oldOID, newOID, kind string, changeID int64, note string) *LogEntry {
	e := &LogEntry{
		Seq:      r.nextSeq,
		Ref:      ref,
		OldOID:   oldOID,
		NewOID:   newOID,
		Actor:    actor,
		Height:   height,
		Kind:     kind,
		ChangeID: changeID,
		Note:     note,
	}
	e.Digest = EntryDigest(r.head, e)
	r.log.Set(seqKey(e.Seq), e)
	r.head = e.Digest
	r.nextSeq++
	return e
}

// SetRef moves a ref by compare-and-swap: expectedOID must be the tip the
// caller last saw ("" to create a ref that does not exist yet). This is git's
// --force-with-lease, except the lease is held by consensus rather than by the
// server you are pushing to, so a concurrent push cannot be silently lost and a
// rewritten history cannot be presented as if it had always been that way.
//
// The chain cannot check that newOID descends from expectedOID: it has no
// objects. That check belongs to a client holding the repo, which is exactly
// why every move is recorded rather than merely applied.
func (r *Repo) SetRef(actor address, height int64, name, expectedOID, newOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleWriter) {
		return nil, ErrUnauthorized
	}
	if !ValidRefName(name) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(newOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	cur := r.Ref(name)
	switch {
	case cur == nil && expectedOID != "":
		return nil, ErrRefNotFound
	case cur != nil && expectedOID == "":
		return nil, ErrRefExists
	case cur != nil && cur.OID != expectedOID:
		return nil, ErrStaleRef
	case cur != nil && cur.OID == newOID:
		return nil, ErrSameOID
	}
	kind := KindUpdate
	old := ""
	if cur == nil {
		kind = KindCreate
	} else {
		old = cur.OID
	}
	r.refs.Set(name, &Ref{Name: name, OID: newOID, UpdatedAt: height, UpdatedBy: actor})
	return r.appendLog(actor, height, name, old, newOID, kind, 0, note), nil
}

// ForceSetRef moves a ref without an expectation. It needs RoleMaintainer and
// is permanently recorded as KindForce: the point is not to forbid a force-push
// (sometimes it is the right call) but to make one impossible to hide.
func (r *Repo) ForceSetRef(actor address, height int64, name, newOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidRefName(name) {
		return nil, ErrInvalidRefName
	}
	if !ValidOID(newOID) {
		return nil, ErrInvalidOID
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	old := ""
	if cur := r.Ref(name); cur != nil {
		if cur.OID == newOID {
			return nil, ErrSameOID
		}
		old = cur.OID
	}
	r.refs.Set(name, &Ref{Name: name, OID: newOID, UpdatedAt: height, UpdatedBy: actor})
	return r.appendLog(actor, height, name, old, newOID, KindForce, 0, note), nil
}

// DeleteRef removes a ref by compare-and-swap. The ref disappears from the
// current state; the log keeps every object it ever pointed at.
//
// Maintainer-only for an economic reason as much as a safety one: on gno.land
// the storage-deposit refund goes to whoever frees the bytes, not to whoever
// paid for them (`receiver := caller` in the vm keeper's deposit path, gno
// master 2026-09-19), so an open delete path pays for vandalism.
func (r *Repo) DeleteRef(actor address, height int64, name, expectedOID, note string) (*LogEntry, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleMaintainer) {
		return nil, ErrUnauthorized
	}
	if !ValidLine(note, MaxNoteLen) {
		return nil, ErrInvalidText
	}
	cur := r.Ref(name)
	if cur == nil {
		return nil, ErrRefNotFound
	}
	if cur.OID != expectedOID {
		return nil, ErrStaleRef
	}
	if name == r.DefaultRef {
		return nil, ErrUnauthorized // the default branch is not deletable
	}
	r.refs.Remove(name)
	return r.appendLog(actor, height, name, cur.OID, "", KindDelete, 0, note), nil
}

// Ref returns the current state of a ref, or nil.
func (r *Repo) Ref(name string) *Ref {
	v := r.refs.Get(name)
	if v == nil {
		return nil
	}
	return v.(*Ref)
}

// IterateRefs walks refs in name order.
func (r *Repo) IterateRefs(cb func(*Ref) bool) {
	r.refs.Iterate("", "", func(_ string, value any) bool {
		return cb(value.(*Ref))
	})
}

// LogHead is the digest of the last entry, "" for an empty log. Pin this value
// anywhere off chain and the whole history becomes falsifiable.
func (r *Repo) LogHead() string { return r.head }

// LogSize is the number of entries ever appended.
func (r *Repo) LogSize() int { return r.log.Size() }

// LogEntryAt returns one entry by sequence number, or nil.
func (r *Repo) LogEntryAt(seq int64) *LogEntry {
	v := r.log.Get(seqKey(seq))
	if v == nil {
		return nil
	}
	return v.(*LogEntry)
}

// IterateLog walks the log oldest-first.
func (r *Repo) IterateLog(offset, count int, cb func(*LogEntry) bool) {
	if count <= 0 {
		count = r.log.Size()
	}
	r.log.IterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*LogEntry))
	})
}

// IterateLogReverse walks the log newest-first, which is what a UI wants.
func (r *Repo) IterateLogReverse(offset, count int, cb func(*LogEntry) bool) {
	if count <= 0 {
		count = r.log.Size()
	}
	r.log.ReverseIterateByOffset(offset, count, func(_ string, value any) bool {
		return cb(value.(*LogEntry))
	})
}

// VerifyLog recomputes the whole digest chain and reports the first entry whose
// digest does not follow from its predecessor. It should be impossible on a
// live chain: it is here because a transparency log nobody can verify is just
// a log, and a client should be running this against the values it read back.
func (r *Repo) VerifyLog() (bool, int64) {
	prev := ""
	bad := int64(-1)
	r.log.Iterate("", "", func(_ string, value any) bool {
		e := value.(*LogEntry)
		if EntryDigest(prev, e) != e.Digest {
			bad = e.Seq
			return true
		}
		prev = e.Digest
		return false
	})
	return bad < 0, bad
}

package forge

import "strings"

// Size caps for a release.
const (
	MaxTagLen     = 64
	MaxRelNameLen = 200
	MaxNotesLen   = 8192
)

// Release is a named point in a repo's history, with notes.
//
// A tag ref already says "this name points at this object". A release says why
// anyone should care: what changed, whether it is ready, and which deployed
// package paths came out of it. That last part is the one an explorer wants,
// and it is also the only honest bridge between a git object id and an on-chain
// deploy, because the chain cannot verify either against the other.
type Release struct {
	Tag        string // "v1.2.0", the key; immutable once cut
	Name       string // human title, may be empty
	Notes      string // markdown, may be empty
	OID        string // the object this release names
	Ref        string // the tag ref, "" if the release does not have one
	Prerelease bool
	CreatedAt  int64 // block height
	CreatedBy  address
	Yanked     bool // withdrawn; kept, because a version that existed cannot un-exist
	YankReason string
}

// ValidTag reports whether s is usable as a release tag.
//
// Not semver-enforcing: gno.land's own packages version as v0, v1 with no minor
// or patch, and a forge that refused those would refuse its own ecosystem.
// Ordering is therefore lexical over a padded form, not semantic, and
// LatestRelease says so.
func ValidTag(s string) bool {
	if s == "" || len(s) > MaxTagLen {
		return false
	}
	if strings.Contains(s, "..") || strings.Contains(s, "/") {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		ok := (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') || c == '.' || c == '-' || c == '_' || c == '+'
		if !ok {
			return false
		}
	}
	return true
}

// CutRelease records a release. The tag is the key and cannot be re-cut: a
// consumer that pinned v1.2.0 and got different bytes later has been lied to,
// and the whole point of a tag is that it does not move. Withdrawing one is
// YankRelease, which leaves it visible.
func (r *Repo) CutRelease(actor address, height int64, tag, name, notes, oid, ref string, prerelease bool) (*Release, error) {
	if r.Archived {
		return nil, ErrRepoArchived
	}
	if !r.Can(actor, RoleWriter) {
		return nil, ErrUnauthorized
	}
	if !ValidTag(tag) {
		return nil, ErrInvalidTag
	}
	if !ValidText(name, MaxRelNameLen) || !ValidText(notes, MaxNotesLen) {
		return nil, ErrInvalidText
	}
	if oid != "" && !ValidOID(oid) {
		return nil, ErrInvalidOID
	}
	if ref != "" && !ValidRefName(ref) {
		return nil, ErrInvalidRefName
	}
	if r.releases.Has(tag) {
		return nil, ErrReleaseExists
	}

	rel := &Release{
		Tag:        tag,
		Name:       name,
		Notes:      notes,
		OID:        oid,
		Ref:        ref,
		Prerelease: prerelease,
		CreatedAt:  height,
		CreatedBy:  actor,
	}
	r.releases.Set(tag, rel)
	r.releaseOrder.Set(seqKey(int64(r.releases.Size())), tag)
	return rel, nil
}

// YankRelease marks a release withdrawn without deleting it.
//
// Deleting would make a pinned version silently vanish, which reads to a
// consumer as "this was never published" rather than "do not use this".
func (r *Repo) YankRelease(actor address, tag, reason string) error {
	if !r.Can(actor, RoleWriter) {
		return ErrUnauthorized
	}
	if !ValidText(reason, MaxNoteLen) {
		return ErrInvalidText
	}
	v := r.releases.Get(tag)
	if v == nil {
		return ErrReleaseNotFound
	}
	rel := v.(*Release)
	rel.Yanked = true
	rel.YankReason = reason
	return nil
}

// Release returns one release by tag, or nil.
func (r *Repo) Release(tag string) *Release {
	v := r.releases.Get(tag)
	if v == nil {
		return nil
	}
	return v.(*Release)
}

// ReleaseCount is how many releases this repo has cut, yanked ones included.
func (r *Repo) ReleaseCount() int { return r.releases.Size() }

// IterateReleases walks releases newest-cut first.
//
// Cut order, not tag order: tags are not required to be semver here (gno.land's
// own packages are v0 and v1), so there is no total order to sort by that would
// not be wrong for somebody. When they were cut is a fact the forge does know.
func (r *Repo) IterateReleases(offset, count int, cb func(*Release) bool) {
	if count <= 0 {
		count = r.releaseOrder.Size()
	}
	r.releaseOrder.ReverseIterateByOffset(offset, count, func(_ string, v any) bool {
		rel := r.releases.Get(v.(string))
		if rel == nil {
			return false
		}
		return cb(rel.(*Release))
	})
}

// LatestRelease is the most recently cut release that is neither a prerelease
// nor yanked, or nil. "Most recently cut", never "highest version": see
// IterateReleases.
func (r *Repo) LatestRelease() *Release {
	var out *Release
	r.IterateReleases(0, 0, func(rel *Release) bool {
		if rel.Prerelease || rel.Yanked {
			return false
		}
		out = rel
		return true
	})
	return out
}

package forge

import (
	"testing"

	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

func TestValidTag(t *testing.T) {
	cases := []struct {
		name string
		tag  string
		want bool
	}{
		{"semver", "v1.2.0", true},
		// gno.land's own packages are v0 and v1 with no minor or patch. A tag
		// rule that refused those would refuse the ecosystem it serves.
		{"a gno version", "v0", true},
		{"a prerelease", "v1.0.0-rc.1", true},
		{"build metadata", "v1.0.0+build.5", true},
		{"not version shaped at all", "genesis-snapshot", true},
		{"empty", "", false},
		{"a slash", "release/v1", false},
		{"a traversal", "v1..0", false},
		{"a space", "v1 0", false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			uassert.Equal(t, tc.want, ValidTag(tc.tag))
		})
	}
}

func TestCutRelease(t *testing.T) {
	_, r := newRepo(t)

	rel, err := r.CutRelease(carol, 300, "v1.0.0", "First", "it works", oid("a"), "refs/tags/v1.0.0", false)
	urequire.NoError(t, err)
	uassert.Equal(t, "v1.0.0", rel.Tag)
	uassert.Equal(t, "First", rel.Name)
	uassert.Equal(t, int64(300), rel.CreatedAt)
	uassert.False(t, rel.Prerelease)
	uassert.Equal(t, 1, r.ReleaseCount())

	got := r.Release("v1.0.0")
	urequire.True(t, got != nil)
	uassert.Equal(t, "it works", got.Notes)
	uassert.True(t, r.Release("v9.9.9") == nil)
}

// A consumer who pinned v1.2.0 and later got different bytes has been lied to.
// The whole point of a tag is that it does not move.
func TestCutReleaseIsImmutable(t *testing.T) {
	_, r := newRepo(t)

	_, err := r.CutRelease(alice, 300, "v1.0.0", "First", "", oid("a"), "", false)
	urequire.NoError(t, err)
	_, err = r.CutRelease(alice, 400, "v1.0.0", "Second", "", oid("b"), "", false)
	uassert.ErrorIs(t, err, ErrReleaseExists)
	uassert.Equal(t, oid("a"), r.Release("v1.0.0").OID)
}

// Cut order, never tag order: a lexical sort presents v10 before v2 and calls
// it newest, and there is no semver to sort by because the tags are not
// required to be semver.
func TestIterateReleasesIsCutOrderNotTagOrder(t *testing.T) {
	_, r := newRepo(t)

	for i, tag := range []string{"v2.0.0", "v10.0.0", "v3.0.0"} {
		_, err := r.CutRelease(alice, int64(300+i), tag, "", "", "", "", false)
		urequire.NoError(t, err)
	}

	var seen []string
	r.IterateReleases(0, 0, func(rel *Release) bool {
		seen = append(seen, rel.Tag)
		return false
	})
	urequire.Equal(t, 3, len(seen))
	uassert.Equal(t, "v3.0.0", seen[0])
	uassert.Equal(t, "v10.0.0", seen[1])
	uassert.Equal(t, "v2.0.0", seen[2])
}

func TestLatestReleaseSkipsPrereleaseAndYanked(t *testing.T) {
	_, r := newRepo(t)

	_, err := r.CutRelease(alice, 300, "v1.0.0", "", "", "", "", false)
	urequire.NoError(t, err)
	uassert.Equal(t, "v1.0.0", r.LatestRelease().Tag)

	// A prerelease is cut later and is still not the latest.
	_, err = r.CutRelease(alice, 310, "v2.0.0-rc.1", "", "", "", "", true)
	urequire.NoError(t, err)
	uassert.Equal(t, "v1.0.0", r.LatestRelease().Tag)

	_, err = r.CutRelease(alice, 320, "v2.0.0", "", "", "", "", false)
	urequire.NoError(t, err)
	uassert.Equal(t, "v2.0.0", r.LatestRelease().Tag)

	// Yanking moves it back, and does not delete it.
	urequire.NoError(t, r.YankRelease(alice, "v2.0.0", "broken migration"))
	uassert.Equal(t, "v1.0.0", r.LatestRelease().Tag)
	uassert.Equal(t, 3, r.ReleaseCount())
	yanked := r.Release("v2.0.0")
	urequire.True(t, yanked != nil)
	uassert.True(t, yanked.Yanked)
	uassert.Equal(t, "broken migration", yanked.YankReason)
}

func TestLatestReleaseIsNilWhenThereIsNone(t *testing.T) {
	_, r := newRepo(t)
	uassert.True(t, r.LatestRelease() == nil)

	_, err := r.CutRelease(alice, 300, "v1.0.0-rc.1", "", "", "", "", true)
	urequire.NoError(t, err)
	uassert.True(t, r.LatestRelease() == nil)
}

func TestReleaseAuthorityAndValidation(t *testing.T) {
	_, r := newRepo(t)

	_, err := r.CutRelease(dave, 300, "v1.0.0", "", "", "", "", false)
	uassert.ErrorIs(t, err, ErrUnauthorized)
	_, err = r.CutRelease(eve, 300, "v1.0.0", "", "", "", "", false)
	uassert.ErrorIs(t, err, ErrUnauthorized)

	_, err = r.CutRelease(alice, 300, "release/v1", "", "", "", "", false)
	uassert.ErrorIs(t, err, ErrInvalidTag)

	_, err = r.CutRelease(alice, 300, "v1.0.0", "", "", "nothex", "", false)
	uassert.ErrorIs(t, err, ErrInvalidOID)

	_, err = r.CutRelease(alice, 300, "v1.0.0", "", "", "", "v1.0.0", false)
	uassert.ErrorIs(t, err, ErrInvalidRefName)

	uassert.ErrorIs(t, r.YankRelease(dave, "v1.0.0", ""), ErrUnauthorized)
	uassert.ErrorIs(t, r.YankRelease(alice, "v9.9.9", ""), ErrReleaseNotFound)

	urequire.NoError(t, r.SetArchived(alice, true))
	_, err = r.CutRelease(alice, 300, "v1.0.0", "", "", "", "", false)
	uassert.ErrorIs(t, err, ErrRepoArchived)
}

func TestForkInheritsNoReleases(t *testing.T) {
	f, r := newRepo(t)
	_, err := r.CutRelease(alice, 300, "v1.0.0", "", "", "", "", false)
	urequire.NoError(t, err)

	child, err := f.Fork(eve, 310, r.ID, "eve/forge")
	urequire.NoError(t, err)
	uassert.Equal(t, 0, child.ReleaseCount())
	uassert.True(t, child.LatestRelease() == nil)
}

package forge

import "strings"

// Size caps. Every string the chain stores is bounded: an unbounded field is an
// unbounded storage deposit, and on gno.land the deposit is paid per byte by
// whoever writes it (100ugnot/byte at the time of writing).
const (
	MaxRepoPartLen = 39   // per side of "<namespace>/<name>"
	MaxRefNameLen  = 255  // git's own limit for a single ref name
	MaxTitleLen    = 200  // issue / change title
	MaxBodyLen     = 8192 // issue / change body
	MaxCommentLen  = 4096
	MaxDescLen     = 512
	MaxNoteLen     = 140 // single-line note attached to a log entry
	MaxMirrorLen   = 512
	MaxMirrors     = 8
	MaxLabels      = 10
	MaxLabelLen    = 32
)

// ValidOID reports whether s is a git object id: 40 (SHA-1) or 64 (SHA-256)
// lowercase hex characters. Case is fixed so the same object always has the
// same on-chain key and the same digest-chain input.
func ValidOID(s string) bool {
	if len(s) != 40 && len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return false
		}
	}
	return true
}

// ValidRefName reports whether s is a fully-qualified ref name this forge
// accepts: a "refs/"-rooted subset of git-check-ref-format(1).
//
// Deliberately stricter than git: the name must be fully qualified, so there is
// never an ambiguity between "main" the branch and "main" the tag, and a client
// can map an on-chain name onto a local ref without a lookup table.
func ValidRefName(s string) bool {
	if s == "" || len(s) > MaxRefNameLen {
		return false
	}
	if !strings.HasPrefix(s, "refs/") {
		return false
	}
	if strings.Contains(s, "..") || strings.Contains(s, "@{") {
		return false
	}
	if strings.HasSuffix(s, "/") || strings.HasSuffix(s, ".") {
		return false
	}
	parts := strings.Split(s, "/")
	if len(parts) < 2 {
		return false
	}
	for _, p := range parts {
		if p == "" || p == "@" {
			return false
		}
		if strings.HasPrefix(p, ".") || strings.HasSuffix(p, ".lock") {
			return false
		}
		for i := 0; i < len(p); i++ {
			if !refByteOK(p[i]) {
				return false
			}
		}
	}
	return true
}

// refByteOK rejects the bytes git itself rejects in a ref component: ASCII
// control characters, space, DEL, and the pathspec/revision metacharacters.
func refByteOK(c byte) bool {
	if c <= 0x20 || c == 0x7f {
		return false
	}
	switch c {
	case '~', '^', ':', '?', '*', '[', '\\':
		return false
	}
	return true
}

// ValidRepoID reports whether s is "<namespace>/<name>". The name is always a
// lowercase slug; the namespace is either a slug (a claimed user name) or a
// bech32 address (the caller's own). The two shapes cannot collide: an address
// is 40 characters and a slug caps at MaxRepoPartLen, which is 39.
//
// This layer validates the SHAPE only. Whether the caller may claim a given
// namespace is an ownership question that needs a chain, so it belongs to the
// realm (see the realm's README).
func ValidRepoID(s string) bool {
	ns, name, ok := SplitRepoID(s)
	if !ok {
		return false
	}
	return (validSlug(ns) || AddressNamespace(ns)) && validSlug(name)
}

// SplitRepoID splits "<namespace>/<name>" into its two halves. It does not
// validate either half; ok is false only when the id is not two slash-separated
// non-empty parts.
func SplitRepoID(s string) (ns, name string, ok bool) {
	i := strings.Index(s, "/")
	if i <= 0 || i == len(s)-1 || strings.Count(s, "/") != 1 {
		return "", "", false
	}
	return s[:i], s[i+1:], true
}

// AddressNamespace reports whether ns is shaped like a gno bech32 address, the
// namespace every account owns without registering anything. The realm still
// checks that it is the CALLER's address; this only says which of the two
// ownership rules applies.
func AddressNamespace(ns string) bool {
	if len(ns) != 40 || !strings.HasPrefix(ns, "g1") {
		return false
	}
	for i := 2; i < len(ns); i++ {
		if !strings.ContainsRune(bech32Charset, rune(ns[i])) {
			return false
		}
	}
	return true
}

// bech32Charset is bech32's data alphabet: lowercase alphanumerics minus the
// four characters it drops to avoid transcription errors (1, b, i, o).
const bech32Charset = "023456789acdefghjklmnpqrstuvwxyz"

// validSlug: 1..MaxRepoPartLen chars, [a-z0-9] at both ends, [a-z0-9-_.] inside,
// no "..", no "--". Mixed case is rejected rather than folded: two ids that
// differ only in case would be two avl keys and one human-visible name.
func validSlug(s string) bool {
	if s == "" || len(s) > MaxRepoPartLen {
		return false
	}
	if !alnum(s[0]) || !alnum(s[len(s)-1]) {
		return false
	}
	if strings.Contains(s, "..") || strings.Contains(s, "--") {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if alnum(c) || c == '-' || c == '_' || c == '.' {
			continue
		}
		return false
	}
	return true
}

func alnum(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')
}

// ValidText reports whether s fits in max bytes and carries no control
// characters other than newline and tab. Render output is markdown served by
// gnoweb, so a stray control byte is a rendering bug for every reader forever.
func ValidText(s string, max int) bool {
	if len(s) > max {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\n' || c == '\t' {
			continue
		}
		if c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// ValidLine reports whether s is single-line text within max bytes. Used for
// titles and for log-entry notes, which are fields of the digest chain: a
// newline there would let one note impersonate two.
func ValidLine(s string, max int) bool {
	if strings.ContainsAny(s, "\n\t") {
		return false
	}
	return ValidText(s, max)
}

// ValidMirror reports whether s looks like a fetch locator. The chain does not
// resolve it: it only records where the maintainers say the objects are: so
// the check is a shape check, not a promise that anything is reachable.
func ValidMirror(s string) bool {
	if !ValidLine(s, MaxMirrorLen) || s == "" {
		return false
	}
	for _, p := range []string{"https://", "http://", "git://", "ssh://", "ipfs://", "ipns://", "ar://", "rad://", "git@"} {
		if strings.HasPrefix(s, p) {
			return true
		}
	}
	return false
}

// ValidLabel reports whether s is an issue label.
func ValidLabel(s string) bool {
	return s != "" && ValidLine(s, MaxLabelLen) && !strings.Contains(s, ",")
}

package forge

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestValidOID(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"sha1", strings.Repeat("a", 40), true},
		{"sha256", strings.Repeat("0", 64), true},
		{"mixed hex", "0123456789abcdef0123456789abcdef01234567", true},
		{"empty", "", false},
		{"too short", strings.Repeat("a", 39), false},
		{"between lengths", strings.Repeat("a", 41), false},
		{"uppercase", strings.Repeat("A", 40), false},
		{"non hex", strings.Repeat("z", 40), false},
		{"abbreviated", "deadbeef", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidOID(tc.in), tc.name)
	}
}

func TestValidRefName(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"branch", "refs/heads/main", true},
		{"nested branch", "refs/heads/feat/on-chain-log", true},
		{"tag", "refs/tags/v1.0.0", true},
		{"stash-like", "refs/stash", true},
		{"unqualified", "main", false},
		{"empty", "", false},
		{"double slash", "refs/heads//main", false},
		{"double dot", "refs/heads/a..b", false},
		{"at brace", "refs/heads/a@{0}", false},
		{"trailing slash", "refs/heads/", false},
		{"trailing dot", "refs/heads/main.", false},
		{"dot prefix", "refs/heads/.hidden", false},
		{"lock suffix", "refs/heads/main.lock", false},
		{"space", "refs/heads/my branch", false},
		{"caret", "refs/heads/main^", false},
		{"colon", "refs/heads/a:b", false},
		{"tilde", "refs/heads/main~1", false},
		{"question", "refs/heads/what?", false},
		{"star", "refs/heads/*", false},
		{"backslash", "refs/heads/a\\b", false},
		{"control", "refs/heads/a\x01b", false},
		{"too long", "refs/heads/" + strings.Repeat("a", 300), false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidRefName(tc.in), tc.name)
	}
}

func TestValidRepoID(t *testing.T) {
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"simple", "moul/forge", true},
		{"digits", "ns0/repo9", true},
		{"dots and dashes", "moul/gno-contracts.x", true},
		{"underscore", "moul/my_repo", true},
		{"no slash", "forge", false},
		{"two slashes", "a/b/c", false},
		{"empty ns", "/forge", false},
		{"empty name", "moul/", false},
		{"uppercase", "Moul/forge", false},
		{"leading dash", "moul/-forge", false},
		{"trailing dot", "moul/forge.", false},
		{"double dot", "moul/fo..rge", false},
		{"double dash", "moul/fo--rge", false},
		{"space", "moul/my forge", false},
		{"too long", "moul/" + strings.Repeat("a", 40), false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidRepoID(tc.in), tc.name)
	}
}

func TestAddressNamespace(t *testing.T) {
	addr := testutils.TestAddress("alice").String()
	cases := []struct {
		name string
		in   string
		want bool
	}{
		{"a real address", addr, true},
		{"wrong prefix", "x1" + addr[2:], false},
		{"too short", addr[:39], false},
		{"too long", addr + "a", false},
		{"bech32 drops b i o 1", "g1" + strings.Repeat("b", 38), false},
		{"uppercase", "G1" + addr[2:], false},
		{"a slug is not an address", "moul", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, AddressNamespace(tc.in), tc.name)
	}

	// An address namespace is a valid repo id, and it cannot collide with a
	// claimed name: 40 characters is past the slug cap.
	uassert.True(t, ValidRepoID(addr+"/forge"))
	uassert.False(t, ValidRepoID(strings.Repeat("a", 40)+"/forge"))
	uassert.False(t, ValidRepoID(addr+"/"+addr), "the name half is always a slug")
}

func TestSplitRepoID(t *testing.T) {
	ns, name, ok := SplitRepoID("moul/forge")
	uassert.True(t, ok)
	uassert.Equal(t, "moul", ns)
	uassert.Equal(t, "forge", name)

	for _, bad := range []string{"", "moul", "/forge", "moul/", "a/b/c"} {
		_, _, ok := SplitRepoID(bad)
		uassert.False(t, ok, bad)
	}
}

func TestValidTextAndLine(t *testing.T) {
	uassert.True(t, ValidText("hello\nworld\ttab", 64))
	uassert.False(t, ValidText("bell\x07", 64))
	uassert.False(t, ValidText("too long", 3))
	uassert.True(t, ValidText("", 3))

	uassert.True(t, ValidLine("a single line", 64))
	uassert.False(t, ValidLine("two\nlines", 64))
	uassert.False(t, ValidLine("a\ttab", 64))
}

func TestValidMirrorAndLabel(t *testing.T) {
	cases := []struct {
		in   string
		want bool
	}{
		{"https://github.com/moul/gno-contracts.git", true},
		{"git@github.com:moul/gno-contracts.git", true},
		{"ipfs://bafybeihdwdcefgh4dqkjv67uzcmw7ojee6xedzdetojuzjevtenxquvyku", true},
		{"rad://z3gqcJUoA1n9HaHKufZs5FCSGazv5", true},
		{"ar://1QKPaf1AmsK_tSSdUgtVDEYGLuQBOKTNr", true},
		{"ftp://example.com/repo.git", false},
		{"not a url", false},
		{"", false},
	}
	for _, tc := range cases {
		uassert.Equal(t, tc.want, ValidMirror(tc.in), tc.in)
	}

	uassert.True(t, ValidLabel("bug"))
	uassert.False(t, ValidLabel(""))
	uassert.False(t, ValidLabel("a,b"))
	uassert.False(t, ValidLabel(strings.Repeat("x", 33)))
}

func TestParseRoleRoundTrip(t *testing.T) {
	for _, r := range []Role{RoleNone, RoleReader, RoleWriter, RoleMaintainer, RoleAdmin, RoleOwner} {
		got, err := ParseRole(r.String())
		uassert.NoError(t, err, r.String())
		uassert.Equal(t, int(r), int(got), r.String())
	}
	_, err := ParseRole("root")
	uassert.ErrorIs(t, err, ErrInvalidRole)
}

// Package pilot is a realm-driven account: one realm holds the funds and the
// identity, a key pilots it, and its powers are separate realms installed
// afterwards without ever redeploying it. The gno answer to a Gnosis Safe
// with modules.
//
// An account realm keeps a *Pilot private and hands modules a narrow
// [Account] handle. Everything privileged stays on *Pilot, which is never
// returned, so a module can only reach the two methods it needs.
//
// Two ways to delegate, and they differ in exactly one property:
//
//   - A [Purse] is revocable. Every method on it re-enters the declaring
//     package and re-checks the live roster and budget, so Revoke and
//     SetBudget take effect immediately, even on a purse a module retained.
//   - A sub-identity token (rlm.Sub) is permanent. It lets the module act as
//     "<account>#<subpath>" toward any other realm, which a purse cannot do,
//     but the module can mint a banker from it and keep it forever. Removing
//     the module does not take that back; only emptying the sub-address does.
//     Grant one only to code you have read.
//
// Live instance: r/moul/pilot. Demo module: r/moul/x/pilotdemo.
package pilot

import (
	"chain"
	"chain/banker"
	"errors"
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Module is implemented by a module realm and installed into an account.
// The account never imports it: it learns the module only as this interface.
//
// Run is threaded (the leading int keeps it out of crossing-function
// territory, which a /p/ package may not declare). rlm is whatever the
// account chose to delegate: its own sub-identity token for a trusted
// module, or a zero value when the module was installed purse-only.
type Module interface {
	Name() string
	Run(_ int, rlm realm, args string) string
}

// Grant says what a module was given.
type Grant uint8

const (
	// GrantPurse is funds only, revocable at any time.
	GrantPurse Grant = iota
	// GrantIdentity also lends the account's sub-identity. Permanent.
	GrantIdentity
)

func (g Grant) String() string {
	if g == GrantIdentity {
		return "identity"
	}
	return "purse"
}

var (
	ErrNotOwner     = errors.New("pilot: not the owner")
	ErrNotApproved  = errors.New("pilot: path not approved")
	ErrNotInstalled = errors.New("pilot: module not installed")
	ErrRevoked      = errors.New("pilot: module revoked")
	ErrOverBudget   = errors.New("pilot: over budget")
	ErrStaleRealm   = errors.New("pilot: stale realm value")
	ErrBadName      = errors.New("pilot: a path and a subpath are [a-zA-Z0-9._/-] and not empty")
)

type slot struct {
	mod     Module
	subpath string
	grant   Grant
	budget  int64
	spent   int64
	runs    int64
	live    bool
}

// Pilot is the account. The realm that constructs it owns it and must not
// hand it out; hand out [Pilot.Handle] instead.
type Pilot struct {
	owner   address
	host    string        // the account realm's own pkgpath
	vault   banker.Banker // over host's address, minted once at New
	slots   *avl.Tree     // module pkgpath -> *slot
	handle  *Account
}

// Account is the module-facing half: two methods, both keyed on the calling
// realm's OWN pkgpath, which a realm cannot forge for another.
type Account struct {
	p *Pilot
}

// New builds an account owned by the caller of the crossing function that
// reaches it. Call it once, from the account realm, passing that realm's cur.
func New(_ int, rlm realm) *Pilot {
	assertCurrent(0, rlm)
	p := &Pilot{
		owner: rlm.Previous().Address(),
		host:  rlm.PkgPath(),
		vault: banker.NewBanker(banker.BankerTypeRealmSend, rlm),
		slots: avl.NewTree(),
	}
	p.handle = &Account{p: p}
	return p
}

// assertPlain is why Render can interpolate a path without escaping it: the
// only two strings a caller ever puts in the roster are checked here, at write
// time, against the charset a package path and a subpath are built from.
func assertPlain(s string) {
	if s == "" {
		panic(ErrBadName)
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
		case c == '.', c == '/', c == '-', c == '_':
		default:
			panic(ErrBadName)
		}
	}
}

func assertCurrent(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic(ErrStaleRealm)
	}
}

// AssertOwner panics unless the user behind rlm owns the account. Only the
// account realm may call this: rlm must be its own live cur, so that
// rlm.Previous() is the signer and not some intermediary's caller.
func (p *Pilot) AssertOwner(_ int, rlm realm) {
	assertCurrent(0, rlm)
	if rlm.PkgPath() != p.host {
		panic(ErrNotOwner)
	}
	if rlm.Previous().Address() != p.owner {
		panic(ErrNotOwner)
	}
}

// Handle is what an account realm exposes to modules.
func (p *Pilot) Handle() *Account { return p.handle }

func (p *Pilot) Owner() address { return p.owner }
func (p *Pilot) Host() string   { return p.host }

// Address is the account's main treasury.
func (p *Pilot) Address() address { return chain.PackageAddress(p.host) }

// SubAddress is one module's own treasury, derivable off-chain by anyone.
func (p *Pilot) SubAddress(path string) address {
	s := p.mustSlot(path)
	return chain.DerivePkgSubAddr(p.host, s.subpath)
}

func (p *Pilot) mustSlot(path string) *slot {
	s, ok := p.slots.Get(path).(*slot)
	if !ok {
		panic(ErrNotInstalled)
	}
	return s
}

// Approve authorises a package path to install itself later. The code does
// not have to exist yet, which is the whole point: the account is deployed
// once and learns new powers afterwards.
func (p *Pilot) Approve(_ int, rlm realm, path, subpath string, grant Grant, budget int64) {
	p.AssertOwner(0, rlm)
	assertPlain(path)
	assertPlain(subpath)
	if old, ok := p.slots.Get(path).(*slot); ok {
		old.subpath = subpath
		old.grant = grant
		old.budget = budget
		old.spent = 0 // a new approval is a new allowance
		return
	}
	p.slots.Set(path, &slot{subpath: subpath, grant: grant, budget: budget})
}

// SetBudget is the live knob. It applies to a purse a module already holds.
func (p *Pilot) SetBudget(_ int, rlm realm, path string, budget int64) {
	p.AssertOwner(0, rlm)
	p.mustSlot(path).budget = budget
}

// Revoke stops a module. It takes back its purse immediately; it does NOT
// take back a sub-identity that was granted, nor any banker minted from one.
func (p *Pilot) Revoke(_ int, rlm realm, path string) {
	p.AssertOwner(0, rlm)
	p.mustSlot(path).live = false
}

// Fund moves coins from the account's main treasury into a module's
// sub-treasury. For an identity grant this is the permanent blast radius.
func (p *Pilot) Fund(_ int, rlm realm, path string, amount int64) {
	p.AssertOwner(0, rlm)
	s := p.mustSlot(path)
	p.vault.SendCoins(p.Address(), chain.DerivePkgSubAddr(p.host, s.subpath),
		chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// Exec drives an installed module. rlm must be the account realm's own live
// cur: an identity grant mints its sub-token from it, which only the account
// realm's namespace can do.
func (p *Pilot) Exec(_ int, rlm realm, path, args string) string {
	p.AssertOwner(0, rlm)
	s := p.mustSlot(path)
	if !s.live {
		panic(ErrRevoked)
	}
	s.runs++
	if s.grant == GrantIdentity {
		return s.mod.Run(0, rlm.Sub(s.subpath), args)
	}
	return s.mod.Run(0, rlm, args)
}

// Register is called BY the module realm, with its own live cur. The account
// reads the path from the runtime and never from an argument.
func (a *Account) Register(_ int, rlm realm, m Module) {
	assertCurrent(0, rlm)
	path := rlm.PkgPath()
	s, ok := a.p.slots.Get(path).(*slot)
	if !ok {
		panic(ErrNotApproved)
	}
	s.mod = m
	s.live = true
}

// PurseFor hands the calling module its revocable purse.
func (a *Account) PurseFor(_ int, rlm realm) *Purse {
	assertCurrent(0, rlm)
	path := rlm.PkgPath()
	if _, ok := a.p.slots.Get(path).(*slot); !ok {
		panic(ErrNotApproved)
	}
	return &Purse{p: a.p, path: path}
}

// Purse is a capability this package declares, so every use of it runs here
// and is re-checked against live state. That is what makes it revocable,
// where a banker minted from a lent realm token is not.
type Purse struct {
	p    *Pilot
	path string
}

// Pay spends from the account's main treasury, against the module's budget.
func (u *Purse) Pay(to address, amount int64) {
	s, ok := u.p.slots.Get(u.path).(*slot)
	if !ok {
		panic(ErrNotInstalled)
	}
	if !s.live {
		panic(ErrRevoked)
	}
	if amount <= 0 || amount > s.budget-s.spent {
		panic(ErrOverBudget)
	}
	s.spent += amount
	u.p.vault.SendCoins(u.p.Address(), to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// Left is what this module may still spend.
func (u *Purse) Left() int64 {
	s, ok := u.p.slots.Get(u.path).(*slot)
	if !ok || !s.live {
		return 0
	}
	return s.budget - s.spent
}

// Render is the account page. The account realm forwards its Render here.
func (p *Pilot) Render(path string) string {
	var sb strings.Builder
	sb.WriteString("# " + p.host + "\n\n")
	sb.WriteString("| | |\n|---|---|\n")
	sb.WriteString("| owner | " + p.owner.String() + " |\n")
	sb.WriteString("| treasury | " + p.Address().String() + " |\n")
	sb.WriteString(ufmt.Sprintf("| balance | %d ugnot |\n\n", p.balance(p.Address())))

	if p.slots.Size() == 0 {
		sb.WriteString("No power installed yet.\n")
		return sb.String()
	}

	sb.WriteString("## powers\n\n")
	sb.WriteString("| path | grant | identity | state | left | runs | sub-treasury |\n")
	sb.WriteString("|---|---|---|---|---|---|---|\n")
	p.slots.Iterate("", "", func(key string, v any) bool {
		s := v.(*slot)
		state := "approved"
		if s.live {
			state = "installed"
		} else if s.mod != nil {
			state = "revoked"
		}
		sub := chain.DerivePkgSubAddr(p.host, s.subpath)
		sb.WriteString(ufmt.Sprintf("| `%s` | %s | `%s#%s` | %s | %d | %d | %d ugnot |\n",
			key, s.grant.String(), p.host, s.subpath, state,
			s.budget-s.spent, s.runs, p.balance(sub)))
		return false
	})
	return sb.String()
}

func (p *Pilot) balance(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, "ugnot")
}

// untrusted-render: every string Render echoes is either a verb name validated
// by parseSchema against [a-z0-9_] at accept time, or a package path read off a
// crossing frame. No caller-typed payload is ever rendered.
//
// Package facade is the permanent entry point of the "API as data" upgrade
// pattern (pattern G of the exploration; see ../../README.md).
//
// Patterns E and F put a Go interface at the permanent path, which fixes the
// method set at deploy: adding an operation later needs a whole extra realm.
// This one puts a single entry point there instead,
//
//	Call(cur realm, verb, payload string) string
//
// and moves the API into DATA that each implementation declares. The signature
// that can never change is that one line; everything the application does can
// still grow.
//
// Three things fall out of the API being data, and they are the reason to pay
// the price below:
//
//  1. Callers can ENUMERATE it. Verbs, Signature and SchemaText answer without
//     a transaction, so a client discovers the API instead of being compiled
//     against it.
//  2. Payloads are CHECKED before the handler runs, so an arity mistake is one
//     abort with a readable message rather than whatever the handler does with
//     the wrong number of arguments.
//  3. Upgrades can be DIFFED. Accept refuses a handler whose schema would drop
//     or reshape a verb some existing caller depends on, which no amount of Go
//     interface satisfaction can catch: a handler is free to satisfy Handler
//     and answer nothing.
//
// The price is the type system. Arguments are strings a caller encodes, and a
// misspelled verb is an abort at runtime rather than a compile error. Pattern F
// is the other side of that trade and both ship here on purpose.
//
// State is deliberately out of scope. These handlers are pure; where an
// application's data should live is pattern C's question, and the answer does
// not change because the entry point became a string.
package facade

import (
	"strings"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ownable/v0"
	"gno.land/p/nt/ufmt/v0"
)

const owner address = "g1manfred47kzduec920z88wfr64ylksmdcedlf5" // @moul

const prefix = "gno.land/r/moul/x/upgrade/schema/impl/"

// sep is the payload separator. A single byte, because the point here is the
// shape of the boundary and not the encoding: a real one would need escaping,
// and choosing it is a decision this pattern does not make for you.
const sep = "|"

// Handler is the whole interface an implementation satisfies. It never changes,
// because everything that would have changed it is in Schema instead.
type Handler interface {
	// Schema declares the API, one verb per line, "name arg1 arg2".
	Schema() string
	// Invoke runs a verb. The facade has already checked that the verb exists
	// and that args has exactly the declared arity.
	Invoke(verb string, args []string) string
}

type verb struct {
	name   string
	params []string
}

var (
	Ownable = ownable.NewWithAddress(owner)

	candidates = avl.NewTree() // pkgpath -> Handler
	live       Handler
	livePath   string
	liveVerbs  = avl.NewTree() // verb name -> *verb, for lookup
	liveOrder  []string        // the same verbs in DECLARATION order, for listing
)

// Propose nominates the calling realm, exactly as in pattern F. Its schema is
// parsed here so a malformed one is rejected at proposal rather than at accept.
func Propose(cur realm, h Handler) {
	caller := cur.Previous().PkgPath()
	if !strings.HasPrefix(caller, prefix) {
		panic("unauthorized: " + caller + " is not under " + prefix)
	}
	if h == nil {
		panic("handler must not be nil")
	}
	parseSchema(h.Schema()) // panics if malformed
	candidates.Set(caller, h)
}

// Accept promotes a candidate, and refuses one that would break an existing
// caller. This is the check a Go interface cannot express.
func Accept(cur realm, pkgPath string) {
	h, next, order := resolve(cur, pkgPath)
	assertNoRegression(next)
	live, livePath, liveVerbs, liveOrder = h, pkgPath, next, order
}

// AcceptBreaking promotes a candidate that Accept refuses.
//
// It exists because the diff is SYMMETRIC, which is not obvious until it bites:
// once v1 has added a verb, rolling back to v0 drops that verb and is a
// regression by exactly the same rule that protects callers going forward. A
// pattern that can only move forward is worse than one with no diff at all, so
// the escape hatch is required, and making it a separate function is the point:
// the owner has to type a different word, and the audit log shows which one.
//
// Use it to roll back, and to retire a verb nobody calls any more. Not to make
// an upgrade go through.
func AcceptBreaking(cur realm, pkgPath string) {
	h, next, order := resolve(cur, pkgPath)
	live, livePath, liveVerbs, liveOrder = h, pkgPath, next, order
}

// resolve is the owner check and the lookup both accepts share.
func resolve(cur realm, pkgPath string) (Handler, *avl.Tree, []string) {
	Ownable.AssertOwnedBy(cur.Previous().Address())
	v := candidates.Get(pkgPath)
	if v == nil {
		panic("no candidate at " + pkgPath)
	}
	h := v.(Handler)
	t, order := parseSchema(h.Schema())
	return h, t, order
}

// assertNoRegression is the upgrade diff. A new schema may ADD verbs and may not
// remove one or change its arity, because a caller compiled against the old one
// is still out there calling it.
func assertNoRegression(next *avl.Tree) {
	// Walk in DECLARATION order, not avl order, so the verb named in the abort
	// is the first one a reader of the live schema would reach. Iterating the
	// tree reports whichever violation happens to sort first, which makes the
	// message depend on a verb's spelling.
	for _, name := range liveOrder {
		old := liveVerbs.Get(name).(*verb)
		n := next.Get(name)
		if n == nil {
			panic("schema regression: the candidate drops verb " + name + ", which an existing caller may still call; AcceptBreaking overrides")
		}
		if len(n.(*verb).params) != len(old.params) {
			panic("schema regression: the candidate changes the arity of verb " + name + "; AcceptBreaking overrides")
		}
	}
}

// Call is the one signature this realm is committed to forever.
func Call(cur realm, verbName, payload string) string {
	assertLive()
	v := liveVerbs.Get(verbName)
	if v == nil {
		panic("unknown verb " + verbName + ", known: " + strings.Join(Verbs(), ", "))
	}
	spec := v.(*verb)
	args := []string{}
	if payload != "" {
		args = strings.Split(payload, sep)
	}
	if len(args) != len(spec.params) {
		panic(ufmt.Sprintf("verb %s takes %d argument(s), got %d, signature is %s",
			verbName, len(spec.params), len(args), Signature(verbName)))
	}
	return live.Invoke(verbName, args)
}

// Verbs lists the accepted API in DECLARATION order, which is the order the
// handler wrote it in and the order a reader of the schema expects. Iterating
// the avl tree instead would list them alphabetically, silently: caught by a
// test, not by a compiler.
func Verbs() []string {
	return liveOrder
}

// Signature is one verb's shape, as a caller would write it.
func Signature(name string) string {
	v := liveVerbs.Get(name)
	if v == nil {
		return ""
	}
	return name + "(" + strings.Join(v.(*verb).params, ", ") + ")"
}

// SchemaText is the whole accepted API in the declaration format, so a client
// can read back exactly what the handler declared.
func SchemaText() string {
	out := ""
	for _, n := range Verbs() {
		v := liveVerbs.Get(n).(*verb)
		out += n
		for _, p := range v.params {
			out += " " + p
		}
		out += "\n"
	}
	return out
}

// Live is the package path currently serving, or "" before the first Accept.
func Live() string {
	return livePath
}

// Candidates lists every path that has nominated itself, in order.
func Candidates() []string {
	out := []string{}
	candidates.Iterate("", "", func(k string, _ any) bool {
		out = append(out, k)
		return false
	})
	return out
}

func assertLive() {
	if live == nil {
		panic("no handler accepted")
	}
}

// parseSchema turns the declaration text into verbs, and is the only validation
// of a name that Render later echoes.
func parseSchema(text string) (*avl.Tree, []string) {
	t := avl.NewTree()
	order := []string{}
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		fields := strings.Split(line, " ")
		name := fields[0]
		assertIdent(name)
		params := []string{}
		for _, f := range fields[1:] {
			if f == "" {
				continue
			}
			assertIdent(f)
			params = append(params, f)
		}
		if t.Get(name) != nil {
			panic("malformed schema: verb " + name + " declared twice")
		}
		t.Set(name, &verb{name: name, params: params})
		order = append(order, name)
	}
	if t.Size() == 0 {
		panic("malformed schema: no verbs declared")
	}
	return t, order
}

func assertIdent(s string) {
	if s == "" {
		panic("malformed schema: empty name")
	}
	for _, c := range s {
		if !(c >= 'a' && c <= 'z') && !(c >= '0' && c <= '9') && c != '_' {
			panic("malformed schema: " + s + " is not [a-z0-9_]")
		}
	}
}

func Render(_ string) string {
	if live == nil {
		return ufmt.Sprintf("schema/facade/v0: no handler accepted (%d candidate(s))\n", candidates.Size())
	}
	out := ufmt.Sprintf("schema/facade/v0: %s\n", livePath)
	for _, n := range Verbs() {
		out += "- " + Signature(n) + "\n"
	}
	return out
}

package facade

// ExampleRender pins the facade before any handler realm exists. Nothing is
// imported here, so there is no candidate and nothing accepted.
func ExampleRender() {
	print(Render(""))
	// Output:
	// schema/facade/v0: no handler accepted (0 candidate(s))
}

// untrusted-render: this realm stores no string of its own. The only two a
// caller supplies, a module path and its subpath, are written solely by the
// owner through Approve and charset-validated there (p/moul/pilot assertPlain),
// which is what lets Render interpolate them.
// Package pilot is moul's realm-driven account: it holds the funds and the
// identity, moul's key pilots it, and its powers arrive afterwards as
// separate realms that this one never imports.
//
// All behaviour is in gno.land/p/moul/pilot/v0; this realm is the instance.
// Demo of a power: r/moul/x/pilotdemo.
package pilot

import "gno.land/p/moul/pilot/v0"

// owner is pinned in the source rather than taken from whoever calls Claim
// first. A deploy lands in its own block and the claim is a second
// transaction, so an unpinned Claim is a race anyone on chain can win, and
// this account can never be redeployed to undo it.
const owner = "g1manfred47kzduec920z88wfr64ylksmdcedlf5"

var acct *pilot.Pilot

// Claim arms the account. Once, and only by its owner.
func Claim(cur realm) {
	if acct != nil {
		panic("pilot: already claimed")
	}
	if cur.Previous().Address() != owner {
		panic("pilot: only " + owner + " can claim this account")
	}
	acct = pilot.New(0, cur)
}

// Approve authorises a package path to install itself later, under a named
// sub-identity, with a grant and a budget. The code need not exist yet.
func Approve(cur realm, path, subpath string, identity bool, budget int64) {
	grant := pilot.GrantPurse
	if identity {
		grant = pilot.GrantIdentity
	}
	must().Approve(0, cur, path, subpath, grant, budget)
}

// SetBudget changes what a module may still spend, including through a purse
// it already holds.
func SetBudget(cur realm, path string, budget int64) { must().SetBudget(0, cur, path, budget) }

// Revoke stops a module. It cannot take back a granted identity.
func Revoke(cur realm, path string) { must().Revoke(0, cur, path) }

// Fund moves coins from the main treasury into one module's sub-treasury.
func Fund(cur realm, path string, amount int64) { must().Fund(0, cur, path, amount) }

// Exec drives an installed module.
func Exec(cur realm, path, args string) string { return must().Exec(0, cur, path, args) }

// Handle is how a module realm reaches this account. Its two methods key on
// the caller's own pkgpath, which no realm can forge for another.
func Handle() *pilot.Account { return must().Handle() }

// Address is the main treasury.
func Address() address { return must().Address() }

// SubAddress is one module's treasury.
func SubAddress(path string) address { return must().SubAddress(path) }

func Render(path string) string {
	if acct == nil {
		return "# gno.land/r/moul/pilot\n\nUnclaimed.\n"
	}
	return acct.Render(path)
}

func must() *pilot.Pilot {
	if acct == nil {
		panic("pilot: unclaimed")
	}
	return acct
}

