// Package bad is the handler realm that exists to be refused (pattern G; see
// ../../README.md).
//
// It satisfies facade.Handler exactly as well as the others do: same methods,
// same signatures, compiles and proposes itself without complaint. What it does
// is drop the "upper" verb and change "repeat" to take one argument instead of
// two, both of which break a caller already compiled against v0.
//
// Nothing in gno's type system can see that. A Go interface says what methods
// exist, not which verbs the data behind them still answers, which is the whole
// argument for declaring the API as data and diffing it at accept time.
package bad

import (
	facade "gno.land/r/moul/x/upgrade/schema/facade/v0"
)

// schema drops "upper" entirely and gives "repeat" the wrong arity.
const schema = `repeat s`

type handler struct{}

func (handler) Schema() string { return schema }

func (handler) Invoke(verb string, args []string) string {
	return "this handler never gets to run"
}

// Instance exposes the singleton.
func Instance() facade.Handler { return handler{} }

// Path is this realm's own package path.
const Path = "gno.land/r/moul/x/upgrade/schema/impl/bad/v0"

func init(cur realm) {
	facade.Propose(cross(cur), Instance())
}

// Package impl is version 0 of the handler realm of the "API as data" upgrade
// pattern (pattern G; see ../../README.md).
//
// Two verbs, declared as text rather than as a method set. Deploying nominates
// it; the facade owner accepts it by path.
package impl

import (
	"strings"

	facade "gno.land/r/moul/x/upgrade/schema/facade/v0"
)

// schema is this version's whole API. One verb per line, name then parameters.
const schema = `upper s
repeat s n`

type handler struct{}

func (handler) Schema() string { return schema }

func (handler) Invoke(verb string, args []string) string {
	switch verb {
	case "upper":
		return strings.ToUpper(args[0])
	case "repeat":
		return strings.Repeat(args[0], atoi(args[1]))
	}
	// Unreachable: the facade checked the verb against this schema first.
	panic("unknown verb " + verb)
}

// atoi is hand-rolled to keep the failure message about the ARGUMENT rather
// than about strconv, which is the whole difference a typed boundary would have
// made here.
func atoi(s string) int {
	if s == "" {
		panic("expected a number, got an empty argument")
	}
	n := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			panic("expected a number, got " + s)
		}
		n = n*10 + int(c-'0')
		if n > 64 {
			panic("refusing to repeat more than 64 times")
		}
	}
	return n
}

// Instance exposes the singleton.
func Instance() facade.Handler { return handler{} }

// Path is this realm's own package path, the string the facade owner accepts.
const Path = "gno.land/r/moul/x/upgrade/schema/impl/v0"

func init(cur realm) {
	facade.Propose(cross(cur), Instance())
}

// Propose re-nominates this handler, so a rollback needs no redeploy.
func Propose(cur realm) {
	facade.Propose(cross(cur), Instance())
}

// Package impl is version 1 of the handler realm of the "API as data" upgrade
// pattern (pattern G; see ../../README.md).
//
// Three verbs: it ADDS one and keeps both of v0's untouched, which is what
// lets the facade accept it. Growing the API costs no new realm and no new
// signature at the permanent path.
package impl

import (
	"strings"

	facade "gno.land/r/moul/x/upgrade/schema/facade/v0"
)

// schema is this version's whole API. One verb per line, name then parameters.
const schema = `upper s
repeat s n
surround s left right`

type handler struct{}

func (handler) Schema() string { return schema }

func (handler) Invoke(verb string, args []string) string {
	switch verb {
	case "upper":
		return strings.ToUpper(args[0])
	case "repeat":
		return strings.Repeat(args[0], atoi(args[1]))
	case "surround":
		return args[1] + args[0] + args[2]
	}
	// Unreachable: the facade checked the verb against this schema first.
	panic("unknown verb " + verb)
}

// atoi is hand-rolled to keep the failure message about the ARGUMENT rather
// than about strconv, which is the whole difference a typed boundary would have
// made here.
func atoi(s string) int {
	if s == "" {
		panic("expected a number, got an empty argument")
	}
	n := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			panic("expected a number, got " + s)
		}
		n = n*10 + int(c-'0')
		if n > 64 {
			panic("refusing to repeat more than 64 times")
		}
	}
	return n
}

// Instance exposes the singleton.
func Instance() facade.Handler { return handler{} }

// Path is this realm's own package path, the string the facade owner accepts.
const Path = "gno.land/r/moul/x/upgrade/schema/impl/v1"

func init(cur realm) {
	facade.Propose(cross(cur), Instance())
}

// Propose re-nominates this handler, so a rollback needs no redeploy.
func Propose(cur realm) {
	facade.Propose(cross(cur), Instance())
}

package impl

import (
	"testing"

	facade "gno.land/r/moul/x/upgrade/schema/facade/v0"
	bad "gno.land/r/moul/x/upgrade/schema/impl/bad/v0"
	implv0 "gno.land/r/moul/x/upgrade/schema/impl/v0"

	"gno.land/p/nt/uassert/v0"
)

// TestGrowTheAPI is the whole pattern: three handlers propose themselves, the
// API is enumerable without a transaction, it grows without a new signature at
// the permanent path, and the one candidate that would break a caller is
// refused despite satisfying the interface.
func TestGrowTheAPI(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(facade.Ownable.Owner()))
	uassert.Equal(t, 3, len(facade.Candidates()), "all three handlers nominated themselves")

	// v0: two verbs, and a caller can discover them with no transaction.
	facade.Accept(cross(cur), implv0.Path)
	uassert.Equal(t, "upper, repeat", joinVerbs(facade.Verbs()))
	uassert.Equal(t, "repeat(s, n)", facade.Signature("repeat"))
	uassert.Equal(t, "GNO", facade.Call(cross(cur), "upper", "gno"))
	uassert.Equal(t, "abab", facade.Call(cross(cur), "repeat", "ab|2"))

	// The facade checks arity before the handler runs, so the message names the
	// signature rather than whatever the handler would have done.
	uassert.AbortsContains(t, cur, "verb repeat takes 2 argument(s), got 1, signature is repeat(s, n)", func() {
		facade.Call(cross(cur), "repeat", "ab")
	})
	uassert.AbortsContains(t, cur, "unknown verb nope, known: upper, repeat", func() {
		facade.Call(cross(cur), "nope", "")
	})

	// v1 ADDS a verb and keeps the other two, so it is accepted. No new realm,
	// no new signature at the permanent path, and old callers are untouched.
	facade.Accept(cross(cur), Path)
	uassert.Equal(t, "upper, repeat, surround", joinVerbs(facade.Verbs()))
	uassert.Equal(t, "[gno]", facade.Call(cross(cur), "surround", "gno|[|]"))
	uassert.Equal(t, "GNO", facade.Call(cross(cur), "upper", "gno"), "v0's verbs still answer")

	// The refusal. bad satisfies Handler exactly as well as the others do; what
	// it does is drop a verb and reshape another, which only the schema sees.
	uassert.AbortsContains(t, cur, "schema regression: the candidate drops verb upper", func() {
		facade.Accept(cross(cur), bad.Path)
	})
	uassert.Equal(t, Path, facade.Live(), "a refused accept changes nothing")

	// The diff is SYMMETRIC, which the first draft of this test got wrong: now
	// that v1 has added a verb, rolling back to v0 DROPS it and is a regression
	// by the same rule. Accept refuses the rollback.
	uassert.AbortsContains(t, cur, "schema regression: the candidate drops verb surround", func() {
		facade.Accept(cross(cur), implv0.Path)
	})
	uassert.Equal(t, Path, facade.Live())

	// Which is why the override exists. A pattern that can only move forward is
	// worse than one with no diff at all.
	facade.AcceptBreaking(cross(cur), implv0.Path)
	uassert.Equal(t, "upper, repeat", joinVerbs(facade.Verbs()))
	facade.Accept(cross(cur), Path)

	uassert.Equal(t, "upper s\nrepeat s n\nsurround s left right\n", facade.SchemaText())
	uassert.Equal(t, "schema/facade/v0: gno.land/r/moul/x/upgrade/schema/impl/v1\n"+
		"- upper(s)\n- repeat(s, n)\n- surround(s, left, right)\n", facade.Render(""))
}

// TestDispatchCost100 does 100 dispatches through this pattern's entry point,
// so `gno test -print-runtime-metrics` prints a cycle count for a known
// workload. Its twin is TestDispatchCost100 in adminreg/impl/gen1.
//
// It measures what a call costs through each pattern AS SHIPPED, which is the
// number that decides between them. It is NOT the cost of the string boundary
// in isolation: this path also crosses a realm and the typed one does not.
func TestDispatchCost100(cur realm, t *testing.T) {
	// Runs after TestGrowTheAPI, so v1 is already live. Accepting anything here
	// would fight that test's state, and the verb costs the same either way.
	for i := 0; i < 100; i++ {
		facade.Call(cross(cur), "upper", "gno")
	}
	uassert.Equal(t, "GNO", facade.Call(cross(cur), "upper", "gno"))
}

// TestMalformedSchemaIsRejectedAtProposal checks the other validation edge: a
// schema that cannot be parsed never becomes a candidate.
func TestMalformedSchemaIsRejectedAtProposal(cur realm, t *testing.T) {
	uassert.AbortsContains(t, cur, "malformed schema", func() {
		facade.Propose(cross(cur), badSchema{})
	})
}

type badSchema struct{}

func (badSchema) Schema() string                         { return "Upper s" } // capital, not [a-z0-9_]
func (badSchema) Invoke(string, []string) string         { return "" }

func joinVerbs(v []string) string {
	out := ""
	for i, s := range v {
		if i > 0 {
			out += ", "
		}
		out += s
	}
	return out
}

// Package pilotdemo is a power for a realm-driven account: a payout module
// installed into gno.land/p/moul/pilot/v0 after the account was deployed.
//
// It shows both delegation modes side by side:
//
//   - Pay goes through the account's revocable [pilot.Purse]. Revoking the
//     module stops it on the next call, even though this realm still holds
//     the purse object.
//   - Act is only reachable under an identity grant: the account lends its
//     sub-identity, this realm acts as "<account>#<subpath>" toward another
//     realm, and spends the sub-treasury through a banker it mints. That
//     banker is KEPT on purpose, which is what makes an identity grant
//     permanent: revoking stops Exec, not this.
//
// Demo of gno.land/p/moul/pilot/v0. Account instance: r/moul/pilot.
package pilotdemo

import (
	"chain"
	"chain/banker"

	"gno.land/p/moul/pilot/v0"
	"gno.land/p/nt/ufmt/v0"

	account "gno.land/r/moul/pilot/v0"
)

type payout struct {
	purse *pilot.Purse
	kept  banker.Banker // minted from a lent identity, and retained
	sub   address
	dest  address
	paid  int64
}

func (m *payout) Name() string { return "payout" }

// Run is what the account calls. rlm is the account's sub-identity token
// under an identity grant, and its plain cur otherwise.
func (m *payout) Run(_ int, rlm realm, args string) string {
	if !rlm.IsCurrent() {
		panic("pilotdemo: stale realm value")
	}
	if rlm.Subpath() == "" {
		// purse-only grant: no identity to act under
		m.purse.Pay(m.dest, 100)
		m.paid += 100
		return ufmt.Sprintf("paid 100ugnot from the main treasury, %d left", m.purse.Left())
	}

	// identity grant: act as the account toward another realm...
	seen := Echo(cross(rlm))

	// ...and spend the sub-treasury it owns.
	m.sub = rlm.Address()
	m.kept = banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	m.kept.SendCoins(m.sub, m.dest, chain.NewCoins(chain.NewCoin("ugnot", 100)))
	m.paid += 100
	return "acted as " + seen
}

var self = &payout{}

// Install wires this module into moul's account.
func Install(cur realm, dest address) {
	InstallInto(cur, account.Handle(), dest)
}

// InstallInto wires it into ANY account: a module is not bound to one
// instance. gno has no dynamic call, so the handle has to be passed as a
// value, which a `gnokey maketx run` script can do and a MsgCall cannot.
func InstallInto(cur realm, acct *pilot.Account, dest address) {
	self.dest = dest
	acct.Register(0, cur, self)
	self.purse = acct.PurseFor(0, cur)
}

// Echo reports who called it. A crossing call shifts the previous-realm
// stack even into the same realm, so this is what the module's borrowed
// identity looks like from the outside.
func Echo(cur realm) string { return cur.Previous().PkgPath() }

// Payout spends the sub-treasury with the retained banker, reaching the bank
// without re-entering the account. This is the demonstration that an
// identity grant cannot be revoked: it keeps working after Revoke.
func Payout(cur realm, to address, amount int64) {
	if self.kept == nil {
		panic("pilotdemo: no identity was ever granted")
	}
	self.kept.SendCoins(self.sub, to, chain.NewCoins(chain.NewCoin("ugnot", amount)))
}

// Paid is what this module has moved in total.
func Paid() int64 { return self.paid }

func Render(path string) string {
	if self.purse == nil {
		return "# pilotdemo\n\nNot installed.\n"
	}
	return ufmt.Sprintf("# pilotdemo\n\n| | |\n|---|---|\n| destination | %s |\n| purse left | %d ugnot |\n",
		self.dest.String(), self.purse.Left())
}

package pilotdemo

import (
	"chain"
	"chain/banker"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"

	account "gno.land/r/moul/pilot/v0"
)

const modPath = "gno.land/r/moul/x/pilotdemo/v0"

var (
	// r/moul/pilot pins Claim to this address, so the tests have to use it
	owner   = address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")
	dest    = testutils.TestAddress("dest")
	claimed bool
)

// claim is safe to call from every test: realm state carries over between
// test functions, so the account is claimed exactly once per run.
func claim(cur realm) {
	if claimed {
		return
	}
	claimed = true
	account.Claim(cross(cur))
}

func balance(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoin(addr, "ugnot")
}

func TestPurseGrantIsRevocable(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	claim(cur)

	treasury := account.Address()
	testing.IssueCoins(treasury, chain.NewCoins(chain.NewCoin("ugnot", 10_000)))

	testing.SetRealm(testing.NewUserRealm(owner))
	account.Approve(cross(cur), modPath, "payout", false, 250)

	// the module installs itself; the account reads its path from the runtime
	Install(cross(cur), dest)

	testing.SetRealm(testing.NewUserRealm(owner))
	uassert.Equal(t, "paid 100ugnot from the main treasury, 150 left",
		account.Exec(cross(cur), modPath, ""))
	uassert.Equal(t, int64(100), balance(dest))
	uassert.Equal(t, int64(9_900), balance(treasury))

	// the owner revokes. the module still holds the purse object.
	testing.SetRealm(testing.NewUserRealm(owner))
	account.Revoke(cross(cur), modPath)
	uassert.Equal(t, int64(0), self.purse.Left())

	// both doors are shut: through the account...
	testing.SetRealm(testing.NewUserRealm(owner))
	uassert.AbortsContains(t, cur, "revoked", func() {
		account.Exec(cross(cur), modPath, "")
	})
	// ...and through the retained purse, which is the one that matters.
	uassert.AbortsContains(t, cur, "revoked", func() {
		self.purse.Pay(dest, 10)
	})
	uassert.Equal(t, int64(100), balance(dest))
}

func TestIdentityGrantActsAsTheAccount(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	claim(cur)

	testing.SetRealm(testing.NewUserRealm(owner))
	account.Approve(cross(cur), modPath, "payout", true, 250)
	Install(cross(cur), dest)

	sub := account.SubAddress(modPath)
	testing.IssueCoins(account.Address(), chain.NewCoins(chain.NewCoin("ugnot", 10_000)))

	testing.SetRealm(testing.NewUserRealm(owner))
	account.Fund(cross(cur), modPath, 1_000)
	uassert.Equal(t, int64(1_000), balance(sub))

	testing.SetRealm(testing.NewUserRealm(owner))
	got := account.Exec(cross(cur), modPath, "")

	// the module acted as the ACCOUNT's sub-identity, not as itself
	uassert.Equal(t, "acted as gno.land/r/moul/pilot/v0#payout", got)
	uassert.Equal(t, int64(900), balance(sub))
	uassert.Equal(t, int64(100), balance(dest))
}

func TestIdentityGrantOutlivesRevoke(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	claim(cur)

	testing.SetRealm(testing.NewUserRealm(owner))
	account.Approve(cross(cur), modPath, "payout", true, 250)
	Install(cross(cur), dest)

	sub := account.SubAddress(modPath)
	testing.IssueCoins(account.Address(), chain.NewCoins(chain.NewCoin("ugnot", 10_000)))
	testing.SetRealm(testing.NewUserRealm(owner))
	account.Fund(cross(cur), modPath, 1_000)

	testing.SetRealm(testing.NewUserRealm(owner))
	account.Exec(cross(cur), modPath, "") // mints and keeps a banker on the sub-address
	uassert.Equal(t, int64(900), balance(sub))

	// revoke shuts the account door
	testing.SetRealm(testing.NewUserRealm(owner))
	account.Revoke(cross(cur), modPath)
	uassert.AbortsContains(t, cur, "revoked", func() {
		account.Exec(cross(cur), modPath, "")
	})

	// and the retained banker keeps spending anyway. This is the documented
	// cost of an identity grant: revoking is not taking it back.
	testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("anyone")))
	Payout(cross(cur), dest, 900)
	uassert.Equal(t, int64(0), balance(sub))
}

func TestRender(cur realm, t *testing.T) {
	testing.SetRealm(testing.NewUserRealm(owner))
	claim(cur)

	// a fresh approval is a fresh allowance, so this reads the same whatever
	// ran before it
	testing.SetRealm(testing.NewUserRealm(owner))
	account.Approve(cross(cur), modPath, "payout", false, 1_000)
	Install(cross(cur), dest)
	testing.IssueCoins(account.Address(), chain.NewCoins(chain.NewCoin("ugnot", 10_000)))

	testing.SetRealm(testing.NewUserRealm(owner))
	account.Exec(cross(cur), modPath, "")

	uassert.Equal(t, "# pilotdemo\n\n| | |\n|---|---|\n| destination | "+
		dest.String()+" |\n| purse left | 900 ugnot |\n", Render(""))
}
